Hier ist ein Beispiel für einen Discord.js v14 Bot mit einem Befehl `ban`:

```javascript
const { Client, GatewayIntentBits } = require('discord.js');

// Erzeuge einen neuen Client und verbinde ihn mit dem Discord Gateway
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.on('ready', () => {
  console.log(`Bot ist bereit als ${client.user.tag}`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    // Überprüfe, ob der Benutzer berechtigt ist, einen Benutzer zu bannen
    if (!interaction.member.permissions.has('BanMembers')) {
      return interaction.reply({ content: 'Du hast keine Berechtigung, diesen Befehl auszuführen!', ephemeral: true });
    }

    const member = interaction.options.getMember('user');

    if (!member) return interaction.reply({ content: 'Bitte wähle einen gültigen Benutzer aus!', ephemeral: true });

    try {
      await interaction.guild.members.ban(member.id, { days: 7 });
      return interaction.reply({ content: `${member.user.tag} wurde gebannt.` });
    } catch (err) {
      console.error(err);
      return interaction.reply({ content: 'Beim Ban des Benutzers ist ein Fehler aufgetreten.' });
    }
  }
});

client.login(process.env.TOKEN);
```

